export function diffusion(g,{migration=.02,conversion=.03,initial=.05}={}){integer(g,0,1000,'generations');finite(migration,0,1,'replacement fraction');finite(conversion,0,1,'conversion fraction');finite(initial,0,1,'initial farmers');const ancestry=migration===1?(g?1:0):-Math.expm1(g*Math.log1p(-migration));const adoption=g===0?initial:migration===1||conversion===1?1:initial+(1-initial)*(-Math.expm1(g*(Math.log1p(-migration)+Math.log1p(-conversion))));return {adoption,ancestry,conversionContribution:Math.max(0,adoption-ancestry),quantized:adoption===initial&&g>0&&(migration>0||conversion>0)};}
