export function resources({households=500,yieldPerHousehold=2,loss=.1,allocation=.5}={}){integer(households,10,5000,'households');finite(yieldPerHousehold,.5,4,'yield');finite(loss,0,.8,'loss');finite(allocation,0,1,'allocation');const [ny,ey]=dyadic(yieldPerHousehold),[nl,el]=dyadic(loss),[keep,ek]=oneMinus(loss),base=Math.min(ey,0,ey+el),margin=(ny<<BigInt(ey-base))-(1n<<BigInt(-base))-((ny*nl)<<BigInt(ey+el-base)),N=BigInt(households),scaled=margin*N,gross=fromDyadic(ny*N,ey),lost=fromDyadic(ny*nl*N,ey+el),net=fromDyadic(ny*keep*N,ey+ek),subsistence=Math.min(net,households),shortfall=scaled<0n?fromDyadic(-scaled,base):0,surplus=scaled>0n?fromDyadic(scaled,base):0,[na,ea]=dyadic(allocation),[reserveFactor,er]=oneMinus(allocation),specialists=scaled>0n?fromDyadic(scaled*na,base+ea):0,reserve=scaled>0n?fromDyadic(scaled*reserveFactor,base+er):0;return {gross,lost,net,subsistence,shortfall,surplus,specialists,reserve,budgetSign:margin<0n?'shortfall':margin>0n?'surplus':'exactly balanced',budgetBelowRange:margin!==0n&&shortfall===0&&surplus===0,quantized:shortfall>0&&net===households,residual:gross-lost-subsistence-specialists-reserve};}

export function scaling(N,{a=.235,beta=.7}={}){finite(N,1,250000,'population');finite(a,.05,1,'area prefactor');finite(beta,.4,1.2,'exponent');const area=a*Math.exp(beta*Math.log(N)),density=N/area;return {area,density,elasticity:beta,doublingArea:2**beta,doublingDensity:2**(1-beta)};}
export function areaSummary(series,t){if(!dense(series)||series.length<2||series.some((p,j)=>!dense(p)||p.length!==3||p.some(x=>!Number.isFinite(x))||p[1]<0||p[2]<0||(j&&p[0]<=series[j-1][0])))throw new RangeError('increasing dated area estimates');finite(t,series[0][0],series.at(-1)[0],'date');let integral=0;for(let i=1;i<series.length;i++){const [x0,y0]=series[i-1],[x1,y1]=series[i];if(t<=x0)break;const dt=Math.min(t,x1)-x0,y=y0+(y1-y0)*dt/(x1-x0);integral+=dt*(y+y0)/2;}const j=Math.max(0,series.findIndex((p,i)=>i&&p[0]>=t)-1),p=series[j],q=series[j+1],w=(t-p[0])/(q[0]-p[0]),value=p[1]+w*(q[1]-p[1]),uncertainty=p[2]+w*(q[2]-p[2]);return {value,uncertainty,lower:Math.max(0,value-uncertainty),upper:value+uncertainty,integral};}

